CREATE TABLE IF NOT EXISTS crm_guests (id TEXT PRIMARY KEY, full_name TEXT NOT NULL, email TEXT, phone TEXT, birthday TEXT, notes TEXT, source TEXT NOT NULL DEFAULT 'manual', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_guests_email ON crm_guests(lower(email)) WHERE email IS NOT NULL AND email <> '';
CREATE TABLE IF NOT EXISTS crm_email_subscriptions (guest_id TEXT PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('subscribed','unsubscribed','pending')), consent_source TEXT, consent_at TEXT, unsubscribed_at TEXT, FOREIGN KEY(guest_id) REFERENCES crm_guests(id));
CREATE TABLE IF NOT EXISTS crm_email_campaigns (id TEXT PRIMARY KEY, name TEXT NOT NULL, subject TEXT NOT NULL, body_html TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','sending','sent','paused')), created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, scheduled_at TEXT);
CREATE TABLE IF NOT EXISTS crm_email_deliveries (id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL, guest_id TEXT NOT NULL, provider_message_id TEXT, status TEXT NOT NULL DEFAULT 'pending', error_message TEXT, sent_at TEXT, UNIQUE(campaign_id,guest_id), FOREIGN KEY(campaign_id) REFERENCES crm_email_campaigns(id), FOREIGN KEY(guest_id) REFERENCES crm_guests(id));
